-- Rifts World Book 21: Splynn Dimensional Market - its bestiary and its notable NPCs.
-- 4 creatures (migration 074) and 0 notable NPCs (migration 072),
-- with their attacks in stat_attacks (migration 073).
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~371-splynn-creatures-a.sql
--
-- Written by scripts/bestiary-sql.mjs from 1 worker file(s). Every
-- creature row passes creatureFormulaGaps, every value is printable ASCII,
-- and an 8-word shingle check of the prose fields against the book's cached text finds no copied run.

INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES
('kryygorth-hunter', 'Kryygorth Hunter', 'humanoid', 'rifts', 1, 'Wild and arena K-Hunters are usually anarchist, miscreant or diabolic; about half of the domesticated ones are aberrant. Free ones exposed to good characters rise to unprincipled at best.', '{"IQ":"2D6","ME":"3D6","MA":"2D6","PS":"3D6+20","PP":"2D6+12","PE":"2D6+18","PB":"1D6+2","Spd":"1D4x10+18"}', NULL, NULL, '3D6x10', '4D6+PE', '1D6x10', 'I.S.P. is 1D6x10 plus 1D6 per level of experience. P.P.E. is 4D6 plus the P.E. attribute number. P.S. and P.E. are supernatural. Speed is the ground figure; it doubles when swinging and leaping through trees.', NULL, 14, '{"attacks":6,"initiative":5,"strike":3,"parry":2,"dodge":3,"roll":6,"pull":5,"disarm":3,"entangle":4}', 'Six hand to hand or psionic attacks per melee, plus one at levels 3, 5, 8 and 13. Printed as R.C.C. bonuses, on top of attribute and skill bonuses: +5 initiative, +3 strike (claws or tail), +2 parry, +3 dodge, +6 roll with punch or impact, +5 pull punch, +3 disarm, +4 entangle with the tail, +3 save vs poisons and disease, +4 save vs magic illusions, +1 save vs other magic, +5% save vs coma/death. No Hand to Hand Combat skill can be taken; it fights with its natural weapons.', 'The R.C.C. skills, secondary skills and the Dog Boy experience table belong to the Kryygorth Hunter class, not this row.', 'Psionic Invisibility at will and at no I.S.P. cost, stronger than the Super-Psionic power: it holds while the Hunter means harm and lasts until it pounces, and it also hides the Hunter from magical detection, though psionics still find it. Acrobatics 85%, climb 95%/85%, prowl 80% +1% per level, nightvision of 500 feet (152.4 m), a prehensile tail, keen awareness of movement, smells prey up to 2 miles (3.2 km) off, track by smell 70% +2% per level (+10% on a blood trail), recognize scent 75% +1% per level. Leaps 20 feet (6.1 m) high or 30 feet (9.1 m) long. Feeds on P.P.E. like a Psi-Stalker, and can draw it from ordinary beings as well as magic and psionic ones.', 'None.', 'Major psychic. Sixth Sense, Sense Magic, See The Invisible, Detect Psionics and two Sensitive powers of choice, plus the natural Psionic Invisibility (a racial ability). Saves vs psionics on a 12 or higher.', '6-7 feet (1.8-2.1 m) tall, though its crouch makes it look about 30% shorter', '200-250 lbs (90-112.5 kg)', '50 years; some have reached 70', 'Forest and jungle by preference, but found wherever the Splugorth are.', 'None as such; free Hunters often side with feral Dog Boys, wild Psi-Stalkers, Simvan and other primitive or aggressive peoples and intelligent predators.', 'None as such; a slave takes on its master''s enemies.', 'None; an R.C.C. offered as an NPC predator and as an optional player character (the Kryygorth Hunter class).', 'A hunched, reptile-headed predator with green and brown hide, long claws, a mouthful of fangs and a gripping tail it uses to swing through trees like a monkey. Lord Kryygorth''s Bio-Wizards raised its wits and gave it psychic powers so it could hunt thinking prey and creatures of magic, and it now sells as a hunter, tracker and guard that is hard to control but worth the trouble. It naturally preys on the Kryygorth Shellback. It wants little gear beyond a pack, a few trophies and an old melee weapon, and refuses implants. Value: 3D6x100,000 credits for a trained one on average, two to three times that or more for a loyal, strong or experienced one.', 'Rifts World Book 21: Splynn Dimensional Market p.73-75'),
('kryygorths-lesson', 'Kryygorth''s Lesson', 'humanoid', 'rifts', 0, 'Mostly evil or anarchist; very few good. Even freed ones are usually evil or selfish.', '{"IQ":"3D6+2","ME":"3D6+2","MA":"2D6+1","PS":"3D6+22","PP":"3D6","PE":"3D6+18","PB":"1D6+1","Spd":"4D6"}', '3D6x10+PE', '1D6x10+60', '6D6x10', '4D6x10', NULL, 'M.D.C. is 6D6x10 plus 2D6 per level of experience. On S.D.C. worlds it has 3D6x10 plus the P.E. attribute number in Hit Points and 1D6x10+60 S.D.C., natural A.R. 14 (the ar column). P.P.E. is 4D6x10 plus 4D6 per level. No I.S.P. P.S. and P.E. are supernatural. These are the enslaved creature''s figures; emancipation halves the physical attributes, M.D.C. and P.P.E. (the Kryygorth''s Lesson class).', 14, 13, '{"initiative":3,"strike":4,"parry":4,"dodge":2,"roll":2}', 'Attacks are its hand to hand skill''s plus two more per melee (or two magic attacks), plus one at levels 6 and 12. Printed as R.C.C. bonuses, on top of attribute bonuses: +3 initiative, +4 strike and parry, +2 dodge, +2 roll with punch or impact, +4 save vs magic, +2 save vs psionics, +10% save vs coma/death, and immune to poison and disease. Horror Factor 13 (9 once emancipated).', 'The R.C.C. skills, related and secondary skill counts, the Dragon experience table and the emancipated penalties belong to the Kryygorth''s Lesson class, not this row.', 'Sees the invisible, excellent color vision, nightvision 600 feet (182.9 m). The eyes always glow and can light a 90-degree cone out to 500 feet (152.4 m), or fire blasts (see attacks). Dimensional teleport at 44% +4% per level, up to four tries a day. Bio-regenerates 4D6 M.D.C. a minute. Bound at birth by Bio-Wizardry to one master (two at most, such as a married pair), it must obey any order, suicide included, and cannot act against that master in any way; ownership passes on a master''s command, and only the master''s death frees it. A freed Lesson loses the bond and most of its power for good within 24 hours. It cannot take Bio-Wizard implants (any attempt kills it), Bio-Wizard weapons do not work for it, and its regeneration rejects cybernetics.', 'A Ley Line Walker: knows every spell of levels 1-5 plus 10+3D6 more from levels 5-12, picked by the G.M. or the player.', 'None.', 'About 10 feet (3.05 m) tall and heavily built', '500 lbs (225 kg), mostly muscle', 'Up to 1,000 years, though most die within 500', 'Its home world is unknown, perhaps destroyed or held by the Splugorth; met here and there among the Splugorth and across the Megaverse.', 'None as such; freed Lessons take up with anyone, and favor creatures of magic and dimensional travelers. A few work with the Liberated Underground against the Splugorth.', 'The Splugorth and their Minions.', 'None; an R.C.C. This row is the full enslaved creature for the Game Master. The book opens the race to players only once emancipated, and that weaker form is the Kryygorth''s Lesson class.', 'A towering, bloated and supernaturally strong humanoid with glowing eyes, and in truth a spellcaster. The race were once slender dimensional raiders who robbed Lord Kryygorth; he had them hunted down and spent decades having his Bio-Wizards remake the survivors as perfectly obedient slaves, an example to anyone who would cross a Splugorth. Fewer than a million remain, a fifth of them owned by the Splugorth, who sell rather than keep them; Lord Splynncryth holds a hundred, under a hundred are on Rifts Earth (mostly Atlantis), and none has ever been sold at the Splynn market. Value: usually 2D6x10 million credits, often twice that.', 'Rifts World Book 21: Splynn Dimensional Market p.75-77'),
('kryygorth-pegasus', 'Kryygorth Pegasus', 'humanoid', 'rifts', 1, 'Any, most often principled, scrupulous, unprincipled or aberrant; few are selfish or lawless.', '{"IQ":"1D6+7","ME":"2D6+7","MA":"3D6+7","PS":"3D6+14","PP":"2D6+7","PE":"2D6+14","PB":"2D6+14","Spd":"5D6+22"}', NULL, NULL, '2D4x10+28+PE', '1D6x10+PE', NULL, 'M.D.C. is 2D4x10+28 plus the P.E. attribute number, plus 2D6 per level of experience. P.P.E. is 1D6x10 plus the P.E. attribute number, plus 1D6 per level. Speed is the running figure; flying speed is 2D4x10+63 (at least 83, about 57 mph/91 km). I.Q. is average human. P.S. and P.E. are supernatural.', NULL, 12, '{"attacks":4,"initiative":3,"strike":1,"parry":2,"dodge":2,"pull":4}', 'Four hand to hand or two magic attacks per round, plus one physical attack at levels 4, 7 and 14. Printed as R.C.C. bonuses, on top of attribute and skill bonuses: +3 initiative, +1 strike, +2 parry, +2 dodge on the ground or hovering and +5 in flight, +4 pull punch or kick, +1 save vs poisons and disease, +1 save vs magic, +5% save vs coma/death. Printed as a Horror/Awe Factor of 12. After 70 years its speeds drop 5% a decade and its combat bonuses are halved. No Hand to Hand Combat skill in any circumstance.', 'The R.C.C. skills, related and secondary skill counts and the Psi-Stalker experience table belong to the Kryygorth Pegasus class, not this row.', 'Flies, carrying up to two tons, for six hours before resting (three if loaded past half its maximum); pulls twice what it carries, on the ground only. Sees a small target two miles (3.2 km) off, nightvision 2,000 feet (609.6 m), swim 40%, climb 60/40%, land navigation 80% +1% per level. Without taking flight it leaps 30 feet (9.1 m) high and 50 feet (15.2 m) long. Damaged wings heal three times as fast as a human; a lost wing regrows in 1D6+8 months.', 'Globe of Daylight, Chameleon, See the Invisible, Levitation, Breathe Without Air, Heal Wounds and one level one spell of choice, each at its standard P.P.E. cost.', 'None.', '5-6 feet (1.5-1.8 m) at the shoulder, 7-8 feet (2.1-2.4 m) overall, wingspan 15-18 feet (4.6-5.5 m)', '800-1200 lbs (the book''s 544 kg matches neither figure)', '75 years; a few reach 110', 'Plains or mountains by preference, but anywhere. Free herds on Rifts Earth live in and around the Andes, the Himalayas and the Appalachians.', 'None as such; free ones side with peaceful creatures such as Zembahk and true Pegasus, and a few work with the Liberated Underground to free their kind.', 'The Splugorth, their Minions and nearly every evil creature.', 'None; an R.C.C. offered as an NPC slave or villain and as an optional player character (the Kryygorth Pegasus class).', 'A winged horse to rival the true Pegasus in grace, set apart by humanlike forearms ending in two thick fingers and a thumb; it runs on four legs but often stands or sits upright. Most are white, pale grey or blue-tinged; 10% are dark grey and 5% black. Intelligent, sociable and a fine singer with a little magic, it is thought to be another of Lord Kryygorth''s hybrids. Buyers prize it over flying animals as a mount that can also be a companion, though abuse makes it stubborn; it shuns barding and Bio-Wizardry. Value: 600,000 credits or more when domesticated, as little as 100,000 when wild, when it is often chained, clipped and worked.', 'Rifts World Book 21: Splynn Dimensional Market p.77-79'),
('octoman', 'Octoman', 'humanoid', 'rifts', 1, 'Any', '{"IQ":"3D6","ME":"3D6","MA":"2D6","PS":"3D6+8","PP":"3D6+6","PE":"3D6","PB":"1D4","Spd":"2D6+6"}', 'PE+2D6', '1D6x10', '1D6x10+PE', '4D6', NULL, 'M.D.C. is 1D6x10 plus the P.E. attribute number, plus 1D6 per level of experience. On S.D.C. worlds it has the P.E. attribute number +2D6 Hit Points plus 1D6 per level, and 1D6x10 S.D.C., natural A.R. 11 (the ar column). P.P.E. is 4D6 unless it takes a magic O.C.C.', 11, 13, '{"strike":1,"parry":4,"disarm":2,"entangle":3}', 'Attacks are its O.C.C. and combat skill''s plus two more per melee round, from its two pairs of arms. Printed as R.C.C. bonuses, on top of O.C.C., skill and attribute bonuses: natural paired weapons, +1 strike, +4 parry, +3 entangle, +2 disarm.', 'No R.C.C. skills: it takes an O.C.C., and the O.C.C.s open to it are the Octoman class''s. Its skill bonuses are under natural abilities.', 'Ambidextrous and double-jointed; all four arms can strike at once, or two strike and two parry. +5% to mechanical skills, on top of O.C.C. bonuses; a natural climber at +20%; +10% to prowl and pick locks if taken. Heals 2D6 M.D.C. a day and regrows a lost tentacle in 2D6+22 days.', 'None, unless it takes a magic O.C.C.', 'None.', '4-5 feet (1.2-1.5 m) tall, up to triple that stretched up on its leg tips; the arms reach about 5 feet (1.5 m), the legs 10 feet (3 m)', '150-200 lbs (67.5-90 kg)', '150 years', 'Warm, dry country. Many live in the New West of North America and a few elsewhere on the continent; escaped slaves hide in the Refuges and Preserves of Atlantis and here and there in Africa and southern Europe.', 'None as such; most like humans and D-Bees and do not mind creatures of magic.', 'The Splugorth above all. The Coalition kills them on sight.', 'Takes an O.C.C. (the Octoman class names which); a slave counts as a Vagabond or servant, Operator or City Rat. Offered as an NPC villain and as an optional player character.', 'An eight-tentacled alien with a small round body, a bulbous head, two big eyes and a little beak; four tentacles walk with a rolling gait and four slender ones work like hands. Its rubbery skin runs red to brown and cannot change color, its voice is a rasp, and despite the look it is no sea creature and many cannot swim. The Splugorth overran its world some 500 years ago, and its nimble limbs make it a prized Operator, mechanic and gunfighter (four revolvers at once). Free Octomen hate slavers, rescue their kin and often roam as scouts or heroes, but their alien look scares others and they are lonely and gruff. Juicer and M.O.M. conversions fail on them. Value: two to three times a human of the same skills, a gunslinger as much as a human Tattooed Man, about 20,000 credits untrained or young.', 'Rifts World Book 21: Splynn Dimensional Market p.80-82');

INSERT INTO stat_attacks (owner_kind, owner_slug, name, damage, is_mega_damage, range, note, sort) VALUES
('creature', 'kryygorth-hunter', 'Claw strike', 'Supernatural P.S. damage +2D6', 1, NULL, 'M.D.; the claws add 2D6 M.D. to punch and kick damage.', 0),
('creature', 'kryygorth-hunter', 'Leap kick', 'Double kick damage', 1, NULL, 'M.D.; twice its clawed kick damage.', 1),
('creature', 'kryygorth-hunter', 'Tackle or pounce', 'Supernatural P.S. punch damage', 1, NULL, 'M.D.; a standard punch plus the knockdown penalties.', 2),
('creature', 'kryygorth-hunter', 'Head butt', '2D6', 1, NULL, 'M.D.', 3),
('creature', 'kryygorth-hunter', 'Bite', '4D6', 1, NULL, 'M.D.', 4),
('creature', 'kryygorths-lesson', 'Eye blast', '4D6', 1, '500 feet (152.4 m)', 'M.D., up to 4D6; as many blasts per melee as it has hand to hand attacks.', 0),
('creature', 'kryygorth-pegasus', 'Rear leg kick', 'Supernatural P.S. damage +2D6', 1, NULL, 'M.D.; the kick adds 2D6 M.D. to supernatural P.S. damage.', 0),
('creature', 'kryygorth-pegasus', 'Bite', '1D4', 1, NULL, 'M.D.', 1),
('creature', 'octoman', 'Tentacle strike', '2D6', 0, NULL, 'S.D.C., plus any P.S. damage bonus.', 0),
('creature', 'octoman', 'Tentacle kick', '3D6', 0, NULL, 'S.D.C., plus the P.S. damage bonus.', 1),
('creature', 'octoman', 'Head butt', '1D6', 0, NULL, 'S.D.C.', 2);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 4 creatures are in' AS assertion, count(*) AS got, 4 AS want
  FROM creatures WHERE slug IN ('kryygorth-hunter', 'kryygorths-lesson', 'kryygorth-pegasus', 'octoman');
SELECT 'and 3 of them are playable' AS assertion, count(*) AS got, 3 AS want
  FROM creatures WHERE playable = 1 AND slug IN ('kryygorth-hunter', 'kryygorths-lesson', 'kryygorth-pegasus', 'octoman');
SELECT 'the creatures carry 11 attacks' AS assertion, count(*) AS got, 11 AS want
  FROM stat_attacks WHERE owner_kind = 'creature' AND owner_slug IN ('kryygorth-hunter', 'kryygorths-lesson', 'kryygorth-pegasus', 'octoman');

